-- Generated by scripts/gen-recipe-seed.ts. First recipes (#14), built only from catalogue foods.
-- Active from the start; admins edit or hide them in Admin → Recipes. Skips any recipe whose name already exists,
-- and any whose ingredients are no longer all in the catalogue.
insert into public.recipes (name, cuisine, servings, steps, ingredients, active)
select v.name, v.cuisine, v.servings, v.steps, v.ingredients, true
from (values
  ('Dal chawal with salad', 'Indian', 2, array['Rinse the dal and pressure-cook it with turmeric and salt until soft.', 'Cook the rice separately until fluffy.', 'Heat the oil, splutter cumin, add garlic and a pinch of chilli, then pour it over the dal.', 'Serve the dal over rice with the cucumber and tomato salad.']::text[], '[{"foodId":"dal","q":2},{"foodId":"rice","q":2},{"foodId":"salad","q":1},{"foodId":"oil","q":1}]'::jsonb),
  ('Rajma chawal', 'Indian', 2, array['Warm the rajma curry, adding a splash of water if it has thickened.', 'Cook the rice until fluffy.', 'Serve the rajma over the rice with a side of salad and a squeeze of lemon.']::text[], '[{"foodId":"rajma","q":2},{"foodId":"rice","q":2},{"foodId":"salad","q":1}]'::jsonb),
  ('Chole with roti', 'Indian', 2, array['Simmer the chole for a few minutes so the gravy coats the chickpeas.', 'Roll and cook the rotis on a hot tawa until they puff.', 'Serve with sliced onion, tomato and cucumber salad.']::text[], '[{"foodId":"chole","q":2},{"foodId":"chapati","q":4},{"foodId":"salad","q":1}]'::jsonb),
  ('Idli sambar', 'Indian', 2, array['Steam the idli batter in greased moulds for 10 to 12 minutes.', 'Bring the sambar to a simmer while the idlis steam.', 'Rest the idlis for a minute, unmould and serve with hot sambar.']::text[], '[{"foodId":"idli","q":8},{"foodId":"sambar","q":2}]'::jsonb),
  ('Dosa with sambar', 'Indian', 2, array['Heat a tawa and wipe it with a little water.', 'Spread a ladle of batter thinly in circles and cook until golden and crisp.', 'Fold and serve straight away with hot sambar.']::text[], '[{"foodId":"dosa","q":4},{"foodId":"sambar","q":2}]'::jsonb),
  ('Paneer bhurji with roti', 'Indian', 2, array['Sauté onion, tomato and green chilli until soft.', 'Crumble in the paneer, add turmeric and salt and cook for 3 minutes.', 'Finish with coriander and serve with hot rotis and salad.']::text[], '[{"foodId":"paneer-bhurji","q":2},{"foodId":"chapati","q":4},{"foodId":"salad","q":1}]'::jsonb),
  ('Moong khichdi with curd', 'Indian', 2, array['Rinse rice and moong dal together and pressure-cook with turmeric, salt and water.', 'Temper cumin and a pinch of hing in a little oil and stir it in.', 'Serve warm with a katori of curd.']::text[], '[{"foodId":"khichdi","q":2},{"foodId":"curd","q":2}]'::jsonb),
  ('Vegetable poha with peanuts', 'Indian', 2, array['Rinse the poha in a sieve and let it soften for 5 minutes.', 'Toast the peanuts, then sauté mustard seeds, curry leaves, onion and peas.', 'Add turmeric, salt and the poha, toss gently and finish with lemon and coriander.']::text[], '[{"foodId":"poha","q":2},{"foodId":"peanuts","q":0.5}]'::jsonb),
  ('Upma with sprouts', 'Indian', 2, array['Dry-roast the rava until fragrant.', 'Temper mustard seeds and curry leaves, add vegetables and hot water, then stir in the rava.', 'Cover and cook for 3 minutes. Serve with the moong sprouts salad.']::text[], '[{"foodId":"upma","q":2},{"foodId":"sprouts","q":1}]'::jsonb),
  ('Everyday veg thali', 'Indian', 2, array['Cook the dal with turmeric and finish with a cumin tadka.', 'Cook the mixed vegetable sabzi with ginger, tomato and garam masala.', 'Make the rotis on a hot tawa.', 'Plate dal, sabzi, rotis, curd and salad together.']::text[], '[{"foodId":"dal","q":2},{"foodId":"sabzi","q":2},{"foodId":"chapati","q":4},{"foodId":"curd","q":2},{"foodId":"salad","q":1}]'::jsonb),
  ('Egg curry with rice', 'Indian', 2, array['Boil the eggs for 10 minutes, cool and peel.', 'Make an onion-tomato masala in the oil with ginger, garlic and spices.', 'Add water to make a gravy, slip in the halved eggs and simmer for 5 minutes.', 'Serve with rice and a side of sabzi.']::text[], '[{"foodId":"egg","q":4},{"foodId":"rice","q":2},{"foodId":"sabzi","q":1},{"foodId":"oil","q":2}]'::jsonb),
  ('Chicken curry with rice', 'Indian', 2, array['Brown onions in the oil, then add ginger-garlic paste and tomatoes.', 'Add the chicken pieces and spices and sear for a few minutes.', 'Add water, cover and simmer until the chicken is cooked through.', 'Serve with rice and sabzi.']::text[], '[{"foodId":"chicken","q":2},{"foodId":"rice","q":2},{"foodId":"sabzi","q":1},{"foodId":"oil","q":2}]'::jsonb),
  ('Kerala-style fish curry with rice', 'Indian', 2, array['Sauté mustard seeds, curry leaves, shallots and ginger in the oil.', 'Add chilli, turmeric and tamarind water and bring to a simmer.', 'Slide in the fish and cook gently for 6 to 8 minutes.', 'Serve with hot rice.']::text[], '[{"foodId":"fish","q":2},{"foodId":"rice","q":2},{"foodId":"oil","q":2}]'::jsonb),
  ('Curd rice', 'Indian', 2, array['Mash the cooked rice lightly while it is still warm and let it cool.', 'Stir in the curd and salt.', 'Temper mustard seeds, curry leaves and green chilli in the oil and pour it over.']::text[], '[{"foodId":"rice","q":2},{"foodId":"curd","q":2},{"foodId":"oil","q":0.5}]'::jsonb),
  ('Sprouts chaat', 'Indian', 2, array['Steam the moong sprouts for 3 minutes so they stay crunchy.', 'Toss with chopped cucumber, tomato and onion.', 'Season with chaat masala, lemon and coriander.']::text[], '[{"foodId":"sprouts","q":2},{"foodId":"salad","q":1}]'::jsonb),
  ('Aloo paratha with curd', 'Indian', 2, array['Mash boiled potatoes with green chilli, coriander and ajwain.', 'Stuff the dough, roll it out gently and cook on a hot tawa with a little oil.', 'Serve hot with a katori of curd.']::text[], '[{"foodId":"paratha","q":2},{"foodId":"curd","q":2}]'::jsonb),
  ('Chicken biryani with raita', 'Indian', 2, array['Warm the biryani covered so the rice steams through.', 'Whisk the curd with cucumber, roasted cumin and salt for the raita.', 'Serve the biryani with raita and sliced onion salad.']::text[], '[{"foodId":"biryani","q":2},{"foodId":"curd","q":1},{"foodId":"salad","q":1}]'::jsonb),
  ('Egg fried rice', 'Chinese', 2, array['Use cold cooked rice so the grains stay separate.', 'Scramble the eggs in half the oil on high heat and set them aside.', 'Stir-fry chopped vegetables in the rest of the oil, add the rice and toss well.', 'Fold the egg back in and season with soy sauce, pepper and spring onion.']::text[], '[{"foodId":"rice","q":3},{"foodId":"egg","q":4},{"foodId":"sabzi","q":1},{"foodId":"oil","q":2}]'::jsonb),
  ('Tofu and vegetable stir-fry with brown rice', 'Chinese', 2, array['Press the tofu dry and cut it into cubes.', 'Sear the tofu in the oil until golden, then push it to the side.', 'Stir-fry the vegetables with garlic and ginger, then toss everything with soy sauce.', 'Serve over brown rice.']::text[], '[{"foodId":"tofu","q":2},{"foodId":"sabzi","q":2},{"foodId":"brown-rice","q":2},{"foodId":"oil","q":2}]'::jsonb),
  ('Chilli paneer with rice', 'Chinese', 2, array['Cube the paneer and sear it in the oil until lightly golden.', 'Stir-fry onion, capsicum, garlic and green chilli on high heat.', 'Add soy sauce, a little vinegar and the paneer, and toss until coated.', 'Serve with rice.']::text[], '[{"foodId":"paneer","q":2},{"foodId":"sabzi","q":1},{"foodId":"rice","q":2},{"foodId":"oil","q":2}]'::jsonb),
  ('Chicken stir-fry with brown rice', 'Chinese', 2, array['Slice the chicken thinly and season with soy sauce and pepper.', 'Stir-fry it in the oil on high heat until just cooked, then set aside.', 'Stir-fry the vegetables with garlic, return the chicken and toss together.', 'Serve over brown rice.']::text[], '[{"foodId":"chicken","q":2},{"foodId":"sabzi","q":2},{"foodId":"brown-rice","q":2},{"foodId":"oil","q":2}]'::jsonb),
  ('Greek yogurt bowl with fruit and almonds', 'Mediterranean', 2, array['Spoon the Greek yogurt into two bowls.', 'Top with sliced banana and chopped apple.', 'Scatter the almonds over and add a drizzle of honey if you like.']::text[], '[{"foodId":"greek-yogurt","q":2},{"foodId":"banana","q":1},{"foodId":"apple","q":1},{"foodId":"almonds","q":1}]'::jsonb),
  ('Grilled fish with salad', 'Mediterranean', 2, array['Rub the fish with half the oil, lemon, garlic, salt and pepper.', 'Grill or pan-sear for 3 to 4 minutes a side.', 'Toss the salad with the rest of the oil and lemon, and serve with the fish.']::text[], '[{"foodId":"fish","q":2},{"foodId":"salad","q":2},{"foodId":"oil","q":2}]'::jsonb),
  ('Grilled chicken salad', 'Mediterranean', 2, array['Season the chicken with oregano, garlic, lemon, salt and pepper.', 'Grill until cooked through, rest for 5 minutes and slice.', 'Toss the salad with oil and lemon and top with the chicken.']::text[], '[{"foodId":"chicken","q":2},{"foodId":"salad","q":2},{"foodId":"oil","q":1}]'::jsonb),
  ('Overnight oats with banana and peanut butter', 'Continental', 2, array['Mix the oats with the milk in a jar and refrigerate overnight.', 'In the morning, stir and loosen with a splash of milk if needed.', 'Top with sliced banana and the peanut butter.']::text[], '[{"foodId":"oats","q":2},{"foodId":"milk","q":1},{"foodId":"banana","q":1},{"foodId":"peanut-butter","q":1}]'::jsonb),
  ('Scrambled eggs on toast', 'Continental', 2, array['Whisk the eggs with salt and pepper.', 'Cook them slowly in the oil, stirring, until just set.', 'Toast the bread and pile the eggs on top.']::text[], '[{"foodId":"egg","q":4},{"foodId":"bread","q":4},{"foodId":"oil","q":1}]'::jsonb),
  ('Peanut butter banana toast', 'Continental', 2, array['Toast the bread.', 'Spread the peanut butter evenly.', 'Top with banana slices and a pinch of cinnamon.']::text[], '[{"foodId":"bread","q":4},{"foodId":"peanut-butter","q":2},{"foodId":"banana","q":1}]'::jsonb)
) as v(name, cuisine, servings, steps, ingredients)
where not exists (select 1 from public.recipes r where lower(r.name) = lower(v.name))
  and not exists (
    select 1 from jsonb_array_elements(v.ingredients) e
    where not exists (select 1 from public.foods f where f.id = e ->> 'foodId' and f.owner_id is null)
  );
